import math
import time
from functools import lru_cache


def is_prime(n: int) -> bool:
    """trial division. fine for small n, slow for big ones."""
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    limit = int(math.isqrt(n))
    for d in range(3, limit + 1, 2):
        if n % d == 0:
            return False
    return True


def sieve(limit: int) -> list[int]:
    """sieve of eratosthenes. returns every prime <= limit."""
    flags = [True] * (limit + 1)
    flags[0] = flags[1] = False
    for i in range(2, math.isqrt(limit) + 1):
        if flags[i]:
            for j in range(i * i, limit + 1, i):
                flags[j] = False
    return [i for i, ok in enumerate(flags) if ok]


@lru_cache(maxsize=None)
def fib(n: int) -> int:
    """nth fibonacci number. fib(0) == 0, fib(1) == 1."""
    return n if n < 2 else fib(n - 1) + fib(n - 2)


def collatz_steps(n: int) -> int:
    """how many steps until n hits 1? nobody has proven it always does."""
    steps = 0
    while n != 1:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        steps += 1
    return steps


def longest_collatz(limit: int) -> tuple[int, int]:
    best_n, best_steps = 1, 0
    for n in range(1, limit):
        s = collatz_steps(n)
        if s > best_steps:
            best_n, best_steps = n, s
    return best_n, best_steps


def digit_sum(n: int) -> int:
    """sum of decimal digits. e.g. 2**15 = 32768, so the answer is 26."""
    return sum(int(c) for c in str(n))


def main() -> None:
    start = time.perf_counter()
    primes = sieve(10_000)
    print(f"primes below 10k: {len(primes)}")
    print(f"last five: {primes[-5:]}")
    print(f"is 7919 prime? {is_prime(7919)}")
    print(f"fib(90) = {fib(90)}")
    n, steps = longest_collatz(100_000)
    print(f"longest collatz chain under 100k: n={n}, steps={steps}")
    print(f"pi to 10 places: {math.pi:.10f}")
    print(f"e to 10 places: {math.e:.10f}")
    print(f"golden ratio: {(1 + math.sqrt(5)) / 2:.10f}")
    twin = [(p, p + 2) for p in primes if p + 2 in set(primes)]
    print(f"twin prime pairs below 10k: {len(twin)}")
    print(f"largest twin pair: {twin[-1]}")
    print(f"digit sum of 2**1000: {digit_sum(2 ** 1000)}")
    elapsed = time.perf_counter() - start
    print(f"done. took {elapsed:.3f}s")


if __name__ == "__main__":
    main()
